<script lang="ts">import StatusDot from './StatusDot.svelte';import type {AiccStatus} from '../lib/workflow';import type {UiPresentationStatus} from '../lib/uiLifecycleConsumerProjection.ts';export let active='运行';export let statuses:Record<string,UiPresentationStatus|AiccStatus>={};export let onSelect:(tab:string)=>void=()=>{};export let tabs=['运行','UAT','概览','证据','授权'];</script>
